//! Reference tests that verify Rust implementations match Python outputs.
//!
//! These tests read expected values from xlsx fixtures generated by the Python
//! rolling-ta library and verify our Rust implementations produce identical results.
//!
//! Column positions from tests/fixtures/data_sheets.py (0-indexed, NO headers in files):
//! - btc-sma.xlsx: timestamp(0), close(1), sma(2)
//! - btc-ema.xlsx: timestamp(0), close(1), ema(2)
//! - btc-wma.xlsx: timestamp(0), close(1), weights(2), weighted_sum(3), wma(4)
//! - btc-hma.xlsx: timestamp(0), close(1), weights(2), wma_sqrt_sum(3), wma_sqrt(4),
//!                 wma_half_sum(5), wma_half(6), wma_full_sum(7), wma_full(8),
//!                 hma_raw(9), hma_raw_sum(10), hma(11)
//! - btc-rsi.xlsx: timestamp(0), close(1), gain(2), loss(3), gain_14(4), loss_14(5), rsi(6), ...
//! - btc-bb.xlsx: timestamp(0), close(1), sma(2), upper(3), lower(4)
//! - btc-atr.xlsx: timestamp(0), high(1), low(2), close(3), tr(4), atr(5)
//! - btc-obv.xlsx: timestamp(0), close(1), volume(2), up(3), down(4), obv(5)
//! - btc-adx.xlsx: timestamp(0), high(1), low(2), close(3), tr(4), atr(5),
//!                 h-h_p(6), l_p-l(7), +dx(8), -dx(9), +dx_14(10), -dx_14(11),
//!                 +dmi(12), -dmi(13), dx(14), adx(15)
//! - btc-linear_regression.xlsx: timestamp(0), high(1), low(2), close(3), typical(4),
//!                               row(5), intercept(6), slope(7), lr2(8), forecast(9)
//! - btc-vwap.xlsx: timestamp(0), timestamp_mod(1), high(2), low(3), close(4),
//!                  typical(5), volume(6), raw_accum(7), vol_accum(8), vwap(9)
//! - btc-roc.xlsx: timestamp(0), open(1), high(2), low(3), close(4), volume(5), roc_14(6)

use calamine::{open_workbook, Data, Reader, Xlsx};
use rolling_ta::prelude::*;
use rolling_ta::trend::{ADX, ADXConfig, EMA, EMAConfig, HMA, HMAConfig, SMA, SMAConfig, WMA, WMAConfig,
                        LinearRegression, LinearRegressionR2, LinearRegressionForecast, LinearRegressionConfig};
use rolling_ta::momentum::{ROC, ROCConfig, RSI, RSIConfig};
use rolling_ta::volatility::{ATR, ATRConfig, BB, BBConfig, TR};
use rolling_ta::volume::{OBV, VWAP, VWAPConfig};

const EPSILON: f64 = 1e-4; // Tolerance for floating point comparison

/// Helper to read xlsx file columns by position (NO headers in files).
fn read_xlsx_by_position(path: &str, col_indices: &[usize]) -> Vec<Vec<f64>> {
    let mut workbook: Xlsx<_> =
        open_workbook(path).unwrap_or_else(|_| panic!("Failed to open {}", path));

    let sheet_name = workbook.sheet_names()[0].clone();
    let range = workbook
        .worksheet_range(&sheet_name)
        .expect("Failed to read sheet");

    let mut result: Vec<Vec<f64>> = col_indices.iter().map(|_| Vec::new()).collect();

    // Read all rows (no header to skip)
    for row in range.rows() {
        for (result_idx, &col_idx) in col_indices.iter().enumerate() {
            let value = match row.get(col_idx) {
                Some(Data::Float(f)) => *f,
                Some(Data::Int(i)) => *i as f64,
                Some(Data::Empty) => f64::NAN,
                _ => f64::NAN,
            };
            result[result_idx].push(value);
        }
    }

    result
}

/// Build OhlcvSeries from closes only
fn build_ohlcv_from_closes(closes: &[f64]) -> OhlcvSeries {
    OhlcvSeries::from_closes(closes)
}

/// Build OhlcvSeries with high, low, close
fn build_ohlcv_hlc(highs: &[f64], lows: &[f64], closes: &[f64]) -> OhlcvSeries {
    let mut data = OhlcvSeries::with_capacity(closes.len());
    for i in 0..closes.len() {
        data.timestamps.push(i as i64);
        data.opens.push(closes[i]);
        data.highs.push(highs[i]);
        data.lows.push(lows[i]);
        data.closes.push(closes[i]);
        data.volumes.push(0.0);
    }
    data
}

/// Build OhlcvSeries with close and volume
fn build_ohlcv_cv(closes: &[f64], volumes: &[f64]) -> OhlcvSeries {
    let mut data = OhlcvSeries::with_capacity(closes.len());
    for i in 0..closes.len() {
        data.timestamps.push(i as i64);
        data.opens.push(closes[i]);
        data.highs.push(closes[i]);
        data.lows.push(closes[i]);
        data.closes.push(closes[i]);
        data.volumes.push(volumes[i]);
    }
    data
}

/// Build OhlcvSeries with timestamp, high, low, close, volume (for VWAP)
fn build_ohlcv_thlcv(
    timestamps: &[f64],
    highs: &[f64],
    lows: &[f64],
    closes: &[f64],
    volumes: &[f64],
) -> OhlcvSeries {
    let mut data = OhlcvSeries::with_capacity(closes.len());
    for i in 0..closes.len() {
        data.timestamps.push(timestamps[i] as i64);
        data.opens.push(closes[i]); // Use close as open (not needed for VWAP)
        data.highs.push(highs[i]);
        data.lows.push(lows[i]);
        data.closes.push(closes[i]);
        data.volumes.push(volumes[i]);
    }
    data
}

/// Compare two f64 slices, counting matches within epsilon
fn compare_values(name: &str, rust_values: &[f64], true_values: &[f64], epsilon: f64) -> usize {
    let mut comparisons = 0;
    for (i, (rust_val, true_val)) in rust_values.iter().zip(true_values.iter()).enumerate() {
        if !rust_val.is_nan() && !true_val.is_nan() {
            let diff = (rust_val - true_val).abs();
            assert!(
                diff < epsilon,
                "{} mismatch at index {}: Rust={:.6}, Expected={:.6}, diff={:.6}",
                name,
                i,
                rust_val,
                true_val,
                diff
            );
            comparisons += 1;
        }
    }
    comparisons
}

// ============================================================
// SMA Reference Tests
// ============================================================

#[test]
fn sma_matches_reference() {
    // btc-sma.xlsx: timestamp(0), close(1), sma(2)
    let cols = read_xlsx_by_position("resources/data/btc-sma.xlsx", &[1, 2]);
    let closes = &cols[0];
    let expected = &cols[1];

    let data = build_ohlcv_from_closes(closes);

    let mut sma = SMA::new(SMAConfig::new(14));
    sma.calc(&data).unwrap();

    let comparisons = compare_values("SMA", sma.history(), expected, EPSILON);
    println!("SMA: {} values compared successfully", comparisons);
    assert!(
        comparisons > 100,
        "Should have compared many values, got {}",
        comparisons
    );
}

#[test]
fn sma_streaming_matches_batch() {
    let cols = read_xlsx_by_position("resources/data/btc-sma.xlsx", &[1]);
    let closes = &cols[0];

    let data = build_ohlcv_from_closes(closes);

    // Batch calculation
    let mut batch_sma = SMA::new(SMAConfig::new(14));
    batch_sma.calc(&data).unwrap();

    // Streaming calculation
    let mut stream_sma = SMA::new(SMAConfig::new(14));
    for i in 0..data.len() {
        let tick = Ohlcv {
            open: data.opens[i].into(),
            high: data.highs[i].into(),
            low: data.lows[i].into(),
            close: data.closes[i].into(),
            volume: data.volumes[i].into(),
            timestamp: data.timestamps[i].into(),
        };
        stream_sma.update(&tick).unwrap();
    }

    // Compare results
    let epsilon = 1e-6;
    assert_eq!(batch_sma.len(), stream_sma.len());

    for i in 0..batch_sma.len() {
        let batch_val = batch_sma.get(i as isize).unwrap();
        let stream_val = stream_sma.get(i as isize).unwrap();

        // Handle NaN
        if batch_val.is_nan() && stream_val.is_nan() {
            continue;
        } else if batch_val.is_nan() || stream_val.is_nan() {
            panic!(
                "Index {}: batch SMA ({}) and stream SMA ({}) NaN mismatch",
                i, batch_val, stream_val
            );
        }

        assert!(
            (batch_val - stream_val).abs() < epsilon,
            "Index {}: batch SMA ({}) != stream SMA ({})",
            i,
            batch_val,
            stream_val
        );
    }
}

