// ============================================================
// Bollinger Bands Reference Tests
// ============================================================

#[test]
fn bb_matches_reference() {
    // btc-bb.xlsx: timestamp(0), close(1), sma(2), upper(3), lower(4)
    let cols = read_xlsx_by_position("resources/data/btc-bb.xlsx", &[1, 2, 3, 4]);
    let closes = &cols[0];
    let expected_middle = &cols[1];
    let expected_upper = &cols[2];
    let expected_lower = &cols[3];

    let data = build_ohlcv_from_closes(closes);

    let mut bb = BB::new(BBConfig::new(20, 2.0));
    bb.calc(&data).unwrap();

    // Extract component values from BBOutput
    let history = bb.history();
    let rust_upper: Vec<f64> = history.iter().map(|o| o.upper).collect();
    let rust_middle: Vec<f64> = history.iter().map(|o| o.middle).collect();
    let rust_lower: Vec<f64> = history.iter().map(|o| o.lower).collect();

    let upper_cmp = compare_values("BB Upper", &rust_upper, expected_upper, EPSILON);
    let middle_cmp = compare_values("BB Middle", &rust_middle, expected_middle, EPSILON);
    let lower_cmp = compare_values("BB Lower", &rust_lower, expected_lower, EPSILON);

    println!(
        "BB: upper={}, middle={}, lower={} values compared successfully",
        upper_cmp, middle_cmp, lower_cmp
    );
    assert!(
        upper_cmp > 100,
        "Should have compared many upper values, got {}",
        upper_cmp
    );
    assert!(
        middle_cmp > 100,
        "Should have compared many middle values, got {}",
        middle_cmp
    );
    assert!(
        lower_cmp > 100,
        "Should have compared many lower values, got {}",
        lower_cmp
    );
}

#[test]
fn bb_streaming_matches_batch() {
    let cols = read_xlsx_by_position("resources/data/btc-bb.xlsx", &[1]);
    let closes = &cols[0];

    let data = build_ohlcv_from_closes(closes);

    // Batch calculation
    let mut batch_bb = BB::new(BBConfig::new(20, 2.0));
    batch_bb.calc(&data).unwrap();

    // Streaming calculation
    let mut stream_bb = BB::new(BBConfig::new(20, 2.0));
    for i in 0..data.len() {
        let tick = Ohlcv {
            open: data.opens[i].into(),
            high: data.highs[i].into(),
            low: data.lows[i].into(),
            close: data.closes[i].into(),
            volume: data.volumes[i].into(),
            timestamp: data.timestamps[i].into(),
        };
        stream_bb.update(&tick).unwrap();
    }

    // Compare results
    let epsilon = 1e-6;
    assert_eq!(batch_bb.len(), stream_bb.len());

    for i in 0..batch_bb.len() {
        let batch_val = batch_bb.get(i as isize).unwrap();
        let stream_val = stream_bb.get(i as isize).unwrap();

        // Compare upper band
        if batch_val.upper.is_nan() && stream_val.upper.is_nan() {
            // Both NaN is ok
        } else if batch_val.upper.is_nan() || stream_val.upper.is_nan() {
            panic!(
                "Index {}: batch BB upper ({}) and stream BB upper ({}) NaN mismatch",
                i, batch_val.upper, stream_val.upper
            );
        } else {
            assert!(
                (batch_val.upper - stream_val.upper).abs() < epsilon,
                "Index {}: batch BB upper ({}) != stream BB upper ({})",
                i,
                batch_val.upper,
                stream_val.upper
            );
        }

        // Compare middle band
        if batch_val.middle.is_nan() && stream_val.middle.is_nan() {
            // Both NaN is ok
        } else if batch_val.middle.is_nan() || stream_val.middle.is_nan() {
            panic!(
                "Index {}: batch BB middle ({}) and stream BB middle ({}) NaN mismatch",
                i, batch_val.middle, stream_val.middle
            );
        } else {
            assert!(
                (batch_val.middle - stream_val.middle).abs() < epsilon,
                "Index {}: batch BB middle ({}) != stream BB middle ({})",
                i,
                batch_val.middle,
                stream_val.middle
            );
        }

        // Compare lower band
        if batch_val.lower.is_nan() && stream_val.lower.is_nan() {
            // Both NaN is ok
        } else if batch_val.lower.is_nan() || stream_val.lower.is_nan() {
            panic!(
                "Index {}: batch BB lower ({}) and stream BB lower ({}) NaN mismatch",
                i, batch_val.lower, stream_val.lower
            );
        } else {
            assert!(
                (batch_val.lower - stream_val.lower).abs() < epsilon,
                "Index {}: batch BB lower ({}) != stream BB lower ({})",
                i,
                batch_val.lower,
                stream_val.lower
            );
        }
    }
}

