#[test]
fn obv_matches_reference() {
    // btc-obv.xlsx: timestamp(0), close(1), volume(2), up(3), down(4), obv(5)
    let cols = read_xlsx_by_position("resources/data/btc-obv.xlsx", &[1, 2, 5]);
    let closes = &cols[0];
    let volumes = &cols[1];
    let expected = &cols[2];

    let data = build_ohlcv_cv(closes, volumes);

    let mut obv = OBV::default();
    obv.calc(&data).unwrap();

    let history = obv.history();

    // OBV uses relative error due to large values
    let mut comparisons = 0;
    for (i, (rust_val, true_val)) in history.iter().zip(expected.iter()).enumerate() {
        if !rust_val.is_nan() && !true_val.is_nan() {
            let diff = (rust_val - true_val).abs();
            let relative_err = if true_val.abs() > 1.0 {
                diff / true_val.abs()
            } else {
                diff
            };
            assert!(
                relative_err < 0.001, // 0.1% tolerance
                "OBV mismatch at index {}: Rust={:.6}, Expected={:.6}, diff={:.6}",
                i,
                rust_val,
                true_val,
                diff
            );
            comparisons += 1;
        }
    }

    println!("OBV: {} values compared successfully", comparisons);
    assert!(
        comparisons > 100,
        "Should have compared many values, got {}",
        comparisons
    );
}

