// ============================================================
// Hybrid Mode Tests (50% bulk + 50% incremental)
// These tests verify indicators can initialize with batch data
// and then continue receiving live updates correctly.
// ============================================================

#[test]
fn sma_hybrid_mode() {
    let cols = read_xlsx_by_position("resources/data/btc-sma.xlsx", &[1]);
    let closes = &cols[0];
    let data = build_ohlcv_from_closes(closes);

    // Full batch for reference
    let mut batch_sma = SMA::new(SMAConfig::new(14));
    batch_sma.calc(&data).unwrap();

    // Hybrid: 50% bulk, then incremental
    let half = data.len() / 2;
    let first_half = OhlcvSeries {
        timestamps: data.timestamps[..half].to_vec(),
        opens: data.opens[..half].to_vec(),
        highs: data.highs[..half].to_vec(),
        lows: data.lows[..half].to_vec(),
        closes: data.closes[..half].to_vec(),
        volumes: data.volumes[..half].to_vec(),
    };

    let mut hybrid_sma = SMA::new(SMAConfig::new(14));
    hybrid_sma.calc(&first_half).unwrap();

    // Continue with incremental updates
    for i in half..data.len() {
        let tick = Ohlcv {
            open: data.opens[i].into(),
            high: data.highs[i].into(),
            low: data.lows[i].into(),
            close: data.closes[i].into(),
            volume: data.volumes[i].into(),
            timestamp: data.timestamps[i].into(),
        };
        hybrid_sma.update(&tick).unwrap();
    }

    // Compare results
    let epsilon = 1e-6;
    assert_eq!(batch_sma.len(), hybrid_sma.len());

    for i in 0..batch_sma.len() {
        let batch_val = batch_sma.get(i as isize).unwrap();
        let hybrid_val = hybrid_sma.get(i as isize).unwrap();

        if batch_val.is_nan() && hybrid_val.is_nan() {
            continue;
        } else if batch_val.is_nan() || hybrid_val.is_nan() {
            panic!(
                "SMA hybrid mismatch at index {}: batch={}, hybrid={}",
                i, batch_val, hybrid_val
            );
        }

        assert!(
            (batch_val - hybrid_val).abs() < epsilon,
            "SMA hybrid mismatch at index {}: batch={}, hybrid={}",
            i,
            batch_val,
            hybrid_val
        );
    }
}

