#[test]
fn vwap_matches_reference() {
    // btc-vwap.xlsx: timestamp(0), timestamp_mod(1), high(2), low(3), close(4),
    //                typical(5), volume(6), raw_accum(7), vol_accum(8), vwap(9)
    let cols = read_xlsx_by_position(
        "resources/data/btc-vwap.xlsx",
        &[0, 2, 3, 4, 6, 9], // timestamp, high, low, close, volume, vwap
    );
    let timestamps = &cols[0];
    let highs = &cols[1];
    let lows = &cols[2];
    let closes = &cols[3];
    let volumes = &cols[4];
    let expected = &cols[5];

    let data = build_ohlcv_thlcv(timestamps, highs, lows, closes, volumes);

    // Python uses reset_interval = 1440 * 60 = 86400 (daily)
    let mut vwap = VWAP::new(VWAPConfig::new(86400));
    vwap.calc(&data).unwrap();

    let comparisons = compare_values("VWAP", vwap.history(), expected, EPSILON);
    println!("VWAP: {} values compared successfully", comparisons);
    assert!(
        comparisons > 100,
        "Should have compared many values, got {}",
        comparisons
    );
}

#[test]
fn vwap_streaming_matches_batch() {
    let cols = read_xlsx_by_position(
        "resources/data/btc-vwap.xlsx",
        &[0, 2, 3, 4, 6], // timestamp, high, low, close, volume
    );
    let timestamps = &cols[0];
    let highs = &cols[1];
    let lows = &cols[2];
    let closes = &cols[3];
    let volumes = &cols[4];

    let data = build_ohlcv_thlcv(timestamps, highs, lows, closes, volumes);

    // Batch calculation
    let mut batch_vwap = VWAP::new(VWAPConfig::new(86400));
    batch_vwap.calc(&data).unwrap();

    // Streaming calculation
    let mut stream_vwap = VWAP::new(VWAPConfig::new(86400));
    for i in 0..data.len() {
        let tick = Ohlcv {
            open: data.opens[i].into(),
            high: data.highs[i].into(),
            low: data.lows[i].into(),
            close: data.closes[i].into(),
            volume: data.volumes[i].into(),
            timestamp: data.timestamps[i].into(),
        };
        stream_vwap.update(&tick).unwrap();
    }

    // Compare results
    let epsilon = 1e-6;
    assert_eq!(batch_vwap.len(), stream_vwap.len());

    for i in 0..batch_vwap.len() {
        let batch_val = batch_vwap.get(i as isize).unwrap();
        let stream_val = stream_vwap.get(i as isize).unwrap();

        // Handle NaN
        if batch_val.is_nan() && stream_val.is_nan() {
            continue;
        } else if batch_val.is_nan() || stream_val.is_nan() {
            panic!(
                "Index {}: batch VWAP ({}) and stream VWAP ({}) NaN mismatch",
                i, batch_val, stream_val
            );
        }

        assert!(
            (batch_val - stream_val).abs() < epsilon,
            "Index {}: batch VWAP ({}) != stream VWAP ({})",
            i,
            batch_val,
            stream_val
        );
    }
}

