// ROC Reference Tests
// ============================================================

#[test]
fn roc_matches_reference() {
    // btc-roc.xlsx: timestamp(0), open(1), high(2), low(3), close(4), volume(5), roc(6)
    // Excel formula: G15=((E15-E1)/E1)*100 → 14-period lookback where E15=13311 and E1=13319
    let cols = read_xlsx_by_position("resources/data/btc-roc.xlsx", &[4, 6]);
    let closes = &cols[0];
    let expected = &cols[1];

    let data = build_ohlcv_from_closes(closes);

    let mut roc = ROC::new(ROCConfig::new(14)); // Period 14 (Excel row 14 compares to row 1)
    roc.calc(&data).unwrap();

    let history = roc.history();

    let mut comparisons = 0;
    for (i, (rust_val, true_val)) in history.iter().zip(expected.iter()).enumerate() {
        if rust_val.is_nan() && true_val.is_nan() {
            continue;
        }
        if !rust_val.is_nan() && !true_val.is_nan() {
            let diff = (rust_val - true_val).abs();
            assert!(
                diff < EPSILON,
                "ROC mismatch at index {}: Rust={:.6}, Expected={:.6}, diff={:.6}",
                i,
                rust_val,
                true_val,
                diff
            );
            comparisons += 1;
        }
    }

    println!("ROC: {} values compared successfully", comparisons);
    assert!(
        comparisons > 100,
        "Should have compared many ROC values, got {}",
        comparisons
    );
}

